// The real D3DAutoPtr is exercised against a counted lifetime adapter.
// objectRefs includes the external references, matching production's fused
// Object / Interface relationship. No heap deletion is done so an erroneous
// delete followed by resurrection can be reported deterministically.
class D3DRefCounted {
public:
  enum class Ref { Object };
  UID id;
  unsigned objectRefs = 1, externalRefs = 1;
  bool dead = false;
  explicit D3DRefCounted(UID value) : id(value) {}
  UID getId() const { return id; }
  template<Ref> void incRef() {
    if (dead || !objectRefs) active->fail("resurrection:" + std::to_string(id));
    if (active->setterActive && active->lockDepth != 1) active->fail("retain outside original lock");
    ++objectRefs; ++active->increments;
    active->refEvents.push_back("+" + std::to_string(id));
  }
  template<Ref> void decRef() {
    if (active->setterActive && active->lockDepth != 1) active->fail("release outside original lock");
    if (dead || !objectRefs) { active->fail("overrelease:" + std::to_string(id)); return; }
    --objectRefs; ++active->decrements;
    active->refEvents.push_back("-" + std::to_string(id));
    if (!objectRefs) {
      dead = true; ++active->destructionCount;
      active->semantic.push_back("destroy:" + std::to_string(id));
    }
  }
  void dropExternal() {
    require(externalRefs != 0, "external reference already gone");
    --externalRefs;
    decRef<Ref::Object>();
  }
};
