class ClientMessage {
  Commands command;
  UID owner, uid;
  std::vector<UINT> data;
public:
  ClientMessage(Commands cmd, UID object) : command(cmd), owner(object), uid(active->nextUid++) {
    if (active->lockDepth) active->fail("message inside device lock");
  }
  UID get_uid() const { return uid; }
  template<typename... T> void send_many(T... values) { (data.push_back(static_cast<UINT>(values)), ...); }
  void send_data(UINT value) { data.push_back(value); }
  ~ClientMessage() {
    std::ostringstream text;
    text << "message:" << static_cast<UINT>(command) << ':' << owner << ':' << uid;
    for (auto value : data) text << ':' << value;
    active->semantic.push_back(text.str());
    if (command == Commands::IDirect3DDevice9Ex_SetStreamSource && data.size() == 4 && !data[0]) {
      active->hostStream0 = data[1];
    }
    if (command == Commands::IDirect3DDevice9Ex_SetIndices && data.size() == 1) active->hostIndex = data[0];
  }
};

